{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Resminostat, a cinnamohydroxamic acid HDAC inhibitor structurally closest to the query, showed good oral bioavailability in patients, supporting high F for the query's same warhead and aromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A cinnamohydroxamic acid analogue with a fused heteroaromatic core had 43% absolute oral bioavailability in humans, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Belinostat, a cinnamohydroxamic acid HDAC inhibitor, had 33% oral bioavailability in patients, supporting high F for the query's hydroxamic acid warhead.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "TSU-68, an indole-containing drug, had 42% absolute oral bioavailability in humans, supporting high F for the indole-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Bopindolol, a 2-methylindole derivative, had about 70% absolute oral bioavailability in healthy volunteers, supporting high F for the query's indole core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "AFN-1252, a heteroaromatic enamide with similar intravenous and oral pharmacokinetics, had 83% bioavailability, supporting high F for a related aromatic enamide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Ilomastat, a hydroxamic acid MMP inhibitor, did not show good oral bioavailability, but its peptidic scaffold differs substantially from the query's cinnamoyl/indole architecture, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Curcumin has poor oral bioavailability in humans, but it lacks the hydroxamic acid warhead and has distinct solubility and metabolic liabilities, making it a weak contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a cinnamohydroxamic acid HDAC inhibitor with an indole/aminoethyl linker. The closest structural analogues—resminostat, belinostat, and related cinnamohydroxamic acid compounds—show human oral bioavailability of 33–43%, and indole-containing analogues show 42–70% F. The low-F examples are structurally distant or have different metabolic liabilities. Therefore F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "Morgan similarity scores to evidence molecules are modest, so structural transfer relies on pharmacophore and scaffold reasoning.",
    "Contradictory low-F examples are structurally distant and do not strongly constrain the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

